# Generated by Claude Opus 4.6 (Anthropic)
#!/bin/bash
# install_fish.sh — Installs the FISH profiling framework
#
# Components:
#   1. ros2 wrapper (bash — intercepts ros2 run/launch for LTTng tracing)
#   2. Trace session management (bash — LTTng start/stop/counter + daemon)
#   3. Python package (GPU nsys daemon, live collectors, snapshot, logging)
#   4. Settings file (fish_settings.ini)
#
# Output structure per session:
#   ~/fish_traces/<session>/
#     ├── ros2/       — LTTng trace data (callback boundaries, executor, pub/sub)
#     ├── nsys/       — Nsight Systems reports (GPU kernel chains, memory ops)
#     ├── fishlog/    — FISH event logs (kill/resurrect timestamps)
#     └── snapshot/   — System state (process tree, nodes, topics, hz)
#
# Usage: source install_fish.sh

FISH_ROOT=/opt/ros/humble/fish
FISH_BIN=$FISH_ROOT/bin
FISH_SCRIPTS=$FISH_ROOT/scripts
FISH_PYTHON=$FISH_ROOT/python
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
CONFIG_DIR="$REPO_ROOT/config"

mkdir -p $FISH_BIN $FISH_SCRIPTS $FISH_PYTHON/fish

# --- Read events from fish_events.txt ---
if [[ -f "$CONFIG_DIR/fish_events.txt" ]]; then
    EVENTS=$(grep -v '^#' "$CONFIG_DIR/fish_events.txt" | grep -v '^$' | tr '\n' ' ')
else
    echo "[FISH] WARNING: config/fish_events.txt not found, using all events"
    EVENTS=""
fi

# --- Copy Python package ---
if [[ -d "$REPO_ROOT/python/fish" ]]; then
    cp "$REPO_ROOT"/python/fish/*.py $FISH_PYTHON/fish/
else
    echo "[FISH] WARNING: python/fish/ not found, GPU/snapshot features unavailable"
fi

# --- Copy settings file ---
if [[ -f "$CONFIG_DIR/fish_settings.ini" ]]; then
    cp "$CONFIG_DIR/fish_settings.ini" $FISH_ROOT/fish_settings.ini
else
    echo "[FISH] WARNING: config/fish_settings.ini not found, using defaults"
fi

# --- Tracing tiers (config/tiers/*.txt → $FISH_ROOT/tiers) ---
mkdir -p $FISH_ROOT/tiers && cp "$CONFIG_DIR"/tiers/*.txt $FISH_ROOT/tiers/ 2>/dev/null || true

# --- Copy DDS vendor configs (e.g. cyclonedds_autoware.xml) ---
# Referenced from fish_settings.ini [ros] cyclonedds_uri; the ros2 wrapper
# exports CYCLONEDDS_URI=file://$FISH_ROOT/<name> when appropriate.
for _xml in "$CONFIG_DIR"/*.xml; do
    [[ -f "$_xml" ]] && cp "$_xml" $FISH_ROOT/
done

# --- Generate trace session script (bash) ---
cat > $FISH_SCRIPTS/trace_session.sh << TRACE_EOF
#!/bin/bash
# FISH trace session management (LTTng + GPU daemon + snapshot)

FISH_COUNTER=/tmp/fish_session_count
FISH_SESSION_NAME_FILE=/tmp/fish_session_name
FISH_SESSION_DIR_FILE=/tmp/fish_session_dir
FISH_ROOT=/opt/ros/humble/fish
FISH_PYTHON=\$FISH_ROOT/python
REAL_ROS2=\$(which -a ros2 2>/dev/null | grep -v /fish/bin | head -1)
if [[ -z "\$REAL_ROS2" ]]; then
    # Fallback: source ROS setup if not in PATH
    source /opt/ros/humble/setup.bash 2>/dev/null
    REAL_ROS2=\$(which -a ros2 2>/dev/null | grep -v /fish/bin | head -1)
    REAL_ROS2=\${REAL_ROS2:-/opt/ros/humble/bin/ros2}
fi

start_session() {
    SESSION=\$(cat \$FISH_SESSION_NAME_FILE 2>/dev/null)
    if [[ -z "\$SESSION" ]] || ! lttng list "\$SESSION" &>/dev/null; then
        SESSION="fish_\$(date +%Y%m%d_%H%M%S)"
        SESSION_DIR="\$HOME/fish_traces/\$SESSION"
        echo "\$SESSION" > \$FISH_SESSION_NAME_FILE
        echo "\$SESSION_DIR" > \$FISH_SESSION_DIR_FILE

        mkdir -p "\$SESSION_DIR/ros2"
        mkdir -p "\$SESSION_DIR/nsys"
        mkdir -p "\$SESSION_DIR/fishlog"
        mkdir -p "\$SESSION_DIR/snapshot"

        echo "[FISH] Starting trace session: \$SESSION"
        echo "[FISH] Output: \$SESSION_DIR/"
        rm -rf "\$FISH_SESSION_DIR_FILE.stopping" 2>/dev/null || true   # stale stop lock from a previous session
        # Observer CPU set (host_perf_mode.sh split): sessiond → consumerd
        # inherit the affinity; the app's own tracepoint/ring-buffer work stays
        # on the app threads regardless. Empty = unpinned (default).
        _obs() { if [[ -n "\$FISH_OBS_CPUS" ]]; then taskset -c "\$FISH_OBS_CPUS" "\$@"; else "\$@"; fi; }
        [[ -n "\$FISH_OBS_CPUS" ]] && echo "[FISH] observer cpus: \$FISH_OBS_CPUS (sessiond/consumerd, daemon, snapshot)"
        _obs lttng-sessiond --daemonize 2>/dev/null

        # Optional per-instance publish/take events ([trace] per_instance in
        # fish_settings.ini) — appended to the baked whitelist at session
        # start so a measurement run needs no rebuild.
        # Tracing tier (config/tiers/README.md): FISH_TRACE_TIER=min|default|max picks the per-instance
        # event set; unset → 'default' when [trace] per_instance = true, else 'min' (backwards compatible).
        EXTRA_EVENTS=""
        TIER="\${FISH_TRACE_TIER:-}"
        if [[ -z "\$TIER" ]]; then
            if python3 - <<'PYPI' 2>/dev/null
import configparser, sys
c = configparser.ConfigParser(inline_comment_prefixes=("#", ";"))
c.read("/opt/ros/humble/fish/fish_settings.ini")
sys.exit(0 if c.getboolean("trace", "per_instance", fallback=False) else 1)
PYPI
            then TIER=default; else TIER=min; fi
        fi
        if [[ -f "\$FISH_ROOT/tiers/\$TIER.txt" ]]; then
            EXTRA_EVENTS=\$(grep -v '^#' "\$FISH_ROOT/tiers/\$TIER.txt" | grep -v '^$' | tr '\\n' ' ')
        else
            echo "[FISH] WARNING: unknown tier '\$TIER' (no \$FISH_ROOT/tiers/\$TIER.txt) → no per-instance events"; TIER=min
        fi
        # FISH_EXTRA_EVENTS (2026-10-05): further UST events for this session, space or comma separated (e.g. the
        # fishwait24 state-link probes ros2:fish_msg_retain,ros2:fish_msg_release,ros2:fish_msg_type,…) — an
        # experiment knob; events that prove their worth move into a tier file.
        if [[ -n "\${FISH_EXTRA_EVENTS:-}" ]]; then
            EXTRA_EVENTS="\$EXTRA_EVENTS \$(echo "\$FISH_EXTRA_EVENTS" | tr ',' ' ')"
        fi
        echo "[FISH] tracing tier \$TIER → per-instance events: \${EXTRA_EVENTS:-none}"
        echo "\$TIER" > "\$SESSION_DIR/fishlog/tier.txt"
        echo "\$EXTRA_EVENTS" > "\$SESSION_DIR/fishlog/extra_events.txt"
        [[ "\$EXTRA_EVENTS" == *rmw_take* ]] && echo "filter ros2:rmw_take: taken == 1" >> "\$SESSION_DIR/fishlog/extra_events.txt"

        if [[ -n "\$EXTRA_EVENTS" ]]; then
            # per_instance mode ≈ 2x event rate; the boot storm (node init,
            # 300k+ events/s) overflows LTTng-UST's default per-CPU ring
            # buffers (fish_20260817_101732: 11 626 events discarded in 8 s).
            # 'ros2 trace' cannot size channels, so drive lttng directly with
            # the same events/contexts and 4 x 2 MB sub-buffers per CPU
            # (~256 MB on 32 CPUs; memory only — per-event cost is unchanged).
            FISH_SUBBUF_SIZE=\${FISH_SUBBUF_SIZE:-2M}
            FISH_NUM_SUBBUF=\${FISH_NUM_SUBBUF:-4}
            # LTTng-UST ring buffers live in /dev/shm. Docker's default shm is
            # 64 MB; 4 x 2M x 32 CPUs = 256 MB does NOT fit and UST apps then
            # silently fail to register → an EMPTY trace (fish_20260817_105011).
            # Check and degrade instead of failing silently. Run containers
            # with --shm-size=2g for per_instance runs.
            _shm_kb=\$(df -k /dev/shm 2>/dev/null | awk 'NR==2{print \$2}')
            _sub_kb=\$(numfmt --from=iec "\$FISH_SUBBUF_SIZE" 2>/dev/null | awk '{print int(\$1/1024)}')
            _need_kb=\$(( \${_sub_kb:-2048} * FISH_NUM_SUBBUF * \$(nproc) ))
            if [[ -n "\$_shm_kb" && \$_need_kb -gt \$(( _shm_kb / 2 )) ]]; then
                echo "[FISH] WARNING: LTTng buffers need ~\$((_need_kb/1024)) MB shm but /dev/shm is \$((_shm_kb/1024)) MB"
                echo "[FISH]          → falling back to 512K x 4 per CPU. Start the container with --shm-size=2g for larger buffers."
                FISH_SUBBUF_SIZE=512K; FISH_NUM_SUBBUF=4
            fi
            lttng create "\$SESSION" --output="\$SESSION_DIR/ros2/\$SESSION" >/dev/null
            lttng enable-channel -u -s "\$SESSION" fish_ch \\
                --subbuf-size "\$FISH_SUBBUF_SIZE" --num-subbuf "\$FISH_NUM_SUBBUF" >/dev/null
            EV_LIST="$EVENTS \$EXTRA_EVENTS"
            if [[ "\${FISH_KERNEL_SCHED:-0}" == 1 && "\$TIER" != max ]]; then
                # With the kernel session, sched_switch (executor thread sleeping outside a
                # callback = rcl_wait) and sched_waking (its wake-up = release, with the waker)
                # cover what the per-spin UST executor events would add; drop them to save
                # ~3x callback_start in volume. Without the kernel session they are the
                # fallback for release instants (2026-10-03, A0.1).
                EV_LIST=\$(echo "\$EV_LIST" | tr ' ' '\n' | grep -v '^ros2:rclcpp_executor_' | tr '\n' ' ')
                echo "[FISH] kernel session on → UST executor events (wait_for_work/get_next_ready/execute) not enabled"
            fi
            for ev in \$EV_LIST; do
                if [[ "\$ev" == "ros2:rmw_take" ]]; then
                    # rmw_take fires on every executor poll; taken=0 polls carry no
                    # message (no source_timestamp, nothing to pair) and were ~half
                    # of all events in the v5 Autoware traces. Drop them at the
                    # tracepoint (LTTng payload filter) — the model only consumes
                    # taken=1 rows (measure_flows, join_analysis). 2026-09-05.
                    lttng enable-event -u -s "\$SESSION" -c fish_ch "\$ev" --filter 'taken == 1' >/dev/null 2>&1
                else
                    lttng enable-event -u -s "\$SESSION" -c fish_ch "\$ev" >/dev/null 2>&1
                fi
            done
            lttng add-context -u -s "\$SESSION" -c fish_ch -t vpid -t vtid -t procname >/dev/null
            lttng start "\$SESSION" >/dev/null
            echo "[FISH] LTTng session started via lttng CLI (channel fish_ch \$FISH_NUM_SUBBUF x \$FISH_SUBBUF_SIZE / CPU)"
            echo "" > /tmp/fish_trace_pid
        else
            # Spawn the (echo; sleep) | ros2 trace pipeline in its OWN process
            # group via setsid, so stop_session can kill the whole group with a
            # single negative-PID signal. Without this, killing the ros2 trace
            # PID leaves the sibling 'sleep infinity' orphan and the launching
            # container never exits cleanly.
            setsid bash -c "(echo ''; sleep infinity) | \$REAL_ROS2 trace \\
                --session-name \"\$SESSION\" \\
                --path \"\$SESSION_DIR/ros2\" \\
                -u $EVENTS" 2>&1 &
            echo \$! > /tmp/fish_trace_pid
        fi

        # Optional kernel session (FISH_KERNEL_SCHED=1): sched_switch gives each
        # callback window its on-CPU / preempted / blocked split; sched_waking names
        # the thread that wakes another (OpenMP/pthread helpers of a callback, the
        # driver thread that ends a GPU wait). Separate session
        # writing to kernel/, so the ros2/ ingest never sees it. vtid/vpid contexts
        # carry the container-namespace ids the UST trace uses, on the same clock.
        # Needs lttng-modules loaded on the host and /lib/modules in the container.
        # FISH_GOMP_UPROBE=0 (default; the lttng kernel uprobe ABI refused every --userspace-probe on this host 2026-10-03,
        # the LD_PRELOAD shim below replaces it): kernel uprobe on libgomp's GOMP_parallel —
        # one event per OpenMP parallel region start, in the master thread's context (≈50/s in
        # Autoware: NDT 5 regions per scan; also path_optimizer, costmap_generator, yolox ...).
        # ksched_split uses it to count regions per callback and to attribute the pool threads'
        # on-CPU time inside the window (spinning helpers included) to that callback.
        # FISH_KERNEL_FUTEX=1 (default, 2026-10-03, A0.4): futex syscall entry/exit — a thread
        # that blocks on a contended mutex/condvar enters the kernel here, an uncontended
        # lock never does, so this is exactly the lock-blocking we want (ksched_split
        # 'lock_wait' inside callback windows) at a fraction of the user-level lock events.
        rm -f /tmp/fish_ksession_name
        if [[ "\${FISH_KERNEL_SCHED:-0}" == 1 ]]; then
            KSESSION="\${SESSION}_k"
            if lttng create "\$KSESSION" --output="\$SESSION_DIR/kernel" >/dev/null 2>&1 \\
               && lttng enable-channel -k -s "\$KSESSION" ksched --subbuf-size 2M --num-subbuf 4 >/dev/null \\
               && lttng enable-event -k -s "\$KSESSION" -c ksched sched_switch,sched_waking >/dev/null \\
               && { [[ "\${FISH_KERNEL_FUTEX:-1}" != 1 ]] || lttng enable-event -k -s "\$KSESSION" -c ksched --syscall futex >/dev/null; } \\
               && { [[ "\${FISH_GOMP_UPROBE:-0}" != 1 ]] || lttng enable-event -k -s "\$KSESSION" -c ksched --userspace-probe=elf:\$(readlink -f /usr/lib/x86_64-linux-gnu/libgomp.so.1):GOMP_parallel gomp_parallel >/dev/null \\
                    || echo "[FISH] WARNING: GOMP_parallel uprobe not enabled (lttng-modules uprobes? libgomp path?)"; } \\
               && { [[ "\${FISH_GOMP_UPROBE:-0}" != 1 ]] || lttng enable-event -k -s "\$KSESSION" -c ksched --userspace-probe=elf:\$(readlink -f /usr/lib/x86_64-linux-gnu/libgomp.so.1):GOMP_parallel_loop_dynamic gomp_parallel_loop >/dev/null 2>&1 || true; } \\
               && lttng add-context -k -s "\$KSESSION" -c ksched -t vtid -t vpid -t procname >/dev/null \\
               && lttng start "\$KSESSION" >/dev/null; then
                echo "\$KSESSION" > /tmp/fish_ksession_name
                echo "[FISH] kernel sched_switch session \$KSESSION -> \$SESSION_DIR/kernel"
            else
                echo "[FISH] WARNING: kernel sched_switch session did not start (lttng-modules on the host? /lib/modules mounted?)"
            fi
        fi
        sleep 2
        echo "[FISH] Trace session started"

        # Auto-start GPU daemon (also starts live collectors)
        PYTHONPATH=\$FISH_PYTHON:\$PYTHONPATH _obs python3 -m fish.cli gpu daemon start 2>/dev/null
    fi
}

stop_session() {
    SESSION_DIR=\$(cat \$FISH_SESSION_DIR_FILE 2>/dev/null)

    # 0. Idempotent: the daemon (auto_stop after the replay) and the wrapper
    # (SIGTERM trap) both call stop; the second caller must WAIT for the first
    # instead of running a second shutdown snapshot + trace stop in parallel
    # (2026-09-05 split campaign: two concurrent snapshots, 600 s shutdown).
    if ! mkdir "\$FISH_SESSION_DIR_FILE.stopping" 2>/dev/null; then
        _owner=\$(cat "\$FISH_SESSION_DIR_FILE.stopping/pid" 2>/dev/null)
        if [[ -n "\$_owner" ]] && ! kill -0 "\$_owner" 2>/dev/null; then
            # the stop that took the lock died (2026-09-06: killed by its own
            # parent, the daemon) — take over instead of waiting 900 s for nothing
            echo "[FISH] stale stop lock (owner \$_owner gone) — taking over the stop"
            rm -rf "\$FISH_SESSION_DIR_FILE.stopping"
            mkdir "\$FISH_SESSION_DIR_FILE.stopping" 2>/dev/null || return 0
        else
            echo "[FISH] stop already in progress — waiting for it to finish"
            for _i in \$(seq 1 900); do
                [[ -d "\$FISH_SESSION_DIR_FILE.stopping" ]] || break
                _owner=\$(cat "\$FISH_SESSION_DIR_FILE.stopping/pid" 2>/dev/null)
                if [[ -n "\$_owner" ]] && ! kill -0 "\$_owner" 2>/dev/null; then
                    echo "[FISH] stop owner \$_owner died mid-stop — taking over"
                    rm -rf "\$FISH_SESSION_DIR_FILE.stopping"; mkdir "\$FISH_SESSION_DIR_FILE.stopping" 2>/dev/null && break
                fi
                sleep 1
            done
            [[ -f "\$FISH_SESSION_DIR_FILE.stopping/pid" ]] && return 0   # someone else is stopping
            [[ -d "\$FISH_SESSION_DIR_FILE.stopping" ]] || return 0      # the other stop finished
        fi
    fi
    echo \$\$ > "\$FISH_SESSION_DIR_FILE.stopping/pid"
    trap 'rm -rf "\$FISH_SESSION_DIR_FILE.stopping" 2>/dev/null' RETURN

    # 0. Freeze the trace NOW. Everything below (shutdown snapshot = ros2 node
    #    info over ~225 nodes, ~160 s; nsys drain) used to run with LTTng still
    #    recording, so every session ended with a long idle tail of timer
    #    ticks and the probe's own CLI nodes. The sessions are destroyed in
    #    step 3; the discard warnings are printed by this stop.
    SESSION=\$(cat \$FISH_SESSION_NAME_FILE 2>/dev/null)
    if [[ -n "\$SESSION" ]]; then
        lttng stop "\$SESSION" 2>&1 | tee "\$SESSION_DIR/fishlog/lttng_stop.txt" | grep -i "discard" || true
        echo "[FISH] trace frozen at \$(date +%T) (lttng stop \$SESSION)"
    fi
    KSESSION=\$(cat /tmp/fish_ksession_name 2>/dev/null)
    if [[ -n "\$KSESSION" ]]; then
        lttng stop "\$KSESSION" 2>&1 | tee "\$SESSION_DIR/fishlog/lttng_kernel_stop.txt" | grep -i "discard" || true
    fi

    # 1. Shutdown snapshot (ps_tree + component_list — needs live processes)
    echo "[FISH] Taking shutdown snapshot..."
    _obs() { if [[ -n "\$FISH_OBS_CPUS" ]]; then taskset -c "\$FISH_OBS_CPUS" "\$@"; else "\$@"; fi; }
    PYTHONPATH=\$FISH_PYTHON:\$PYTHONPATH _obs python3 -m fish.cli snapshot 2>/dev/null

    # 2. Stop daemon (stops live collectors + flushes nsys reports).
    #    Skipped when the daemon itself runs this stop (auto-stop after the
    #    replay, FISH_STOP_FROM_DAEMON=1): it already stopped collectors and
    #    nsys, and signalling it here kills this very script (see gpu.py).
    if [[ -z "\$FISH_STOP_FROM_DAEMON" ]]; then
        PYTHONPATH=\$FISH_PYTHON:\$PYTHONPATH python3 -m fish.cli gpu daemon stop 2>/dev/null
    else
        echo "[FISH] stop called by the daemon — daemon stop step skipped"
    fi

    # 2b. Belt-and-suspenders drain — two signals decide we're done:
    #     (a) no nsys/qdstrm post-process processes still running, OR
    #     (b) the nsys_report_complete event count stops growing.
    #
    # The OLD logic only checked (b) and broke as soon as the count was
    # stable for 2 seconds. With 0 events ever emitted (e.g. ros2_benchmark
    # spawns nsys at launch time, FISH skips wrapping, no events fire) this
    # exits at 2s — long before the .nsys-rep file is finalised.
    #
    # FISH_NSYS_DRAIN bumped from 60 to 300 to handle multi-container graphs
    # whose nsys post-process can write several MB in parallel.
    if [[ -n "\$SESSION_DIR" ]]; then
        EVT_LOG=\$(ls -t "\$SESSION_DIR/fishlog"/fish_events_*.log 2>/dev/null | head -1)
        if [[ -n "\$EVT_LOG" ]]; then
            DRAIN=\${FISH_NSYS_DRAIN:-300}
            MIN_WAIT=\${FISH_NSYS_MIN_WAIT:-15}   # always wait this long before declaring 'done'
            T0=\$(date +%s)

            # Primary completion signal: count finalised .nsys-rep files in
            # session_dir/nsys. This is binary-agnostic: works regardless of
            # whether the finalize subprocess is nsys, QdstrmImporter,
            # nsys-cli, etc. We wait until file count is stable for N seconds.
            NSYS_DIR="\$SESSION_DIR/nsys"
            _count_reports() {
                if [[ -d "\$NSYS_DIR" ]]; then
                    find "\$NSYS_DIR" -maxdepth 1 -name '*.nsys-rep' -type f 2>/dev/null | wc -l
                else
                    echo 0
                fi
            }
            REPORT_LAST=-1
            REPORT_STABLE_FOR=0

            # _count_session_procs: nsys-related processes that hold the
            # .nsys-rep finalize in flight. Match by EXE path under the
            # nsight-systems install, OR cmdline starting with 'nsys'/QdstrmImporter.
            # CRITICAL: do NOT match by session_dir in cmdline — that catches
            # the FISH LTTng/trace_session processes which intentionally stay
            # alive until AFTER the drain completes, causing a deadlock.
            _count_session_procs() {
                local n=0
                for pid_d in /proc/[0-9]*; do
                    [[ -d "\$pid_d" ]] || continue
                    local cmd exe comm
                    exe=\$(readlink "\$pid_d/exe" 2>/dev/null || echo "")
                    comm=\$(cat "\$pid_d/comm" 2>/dev/null || echo "")
                    cmd=\$(tr '\\0' ' ' < "\$pid_d/cmdline" 2>/dev/null || echo "")
                    # nsys main + finalize subprocesses
                    if [[ "\$exe" == */nsight-systems*/target-*/* ]] \\
                       || [[ "\$comm" == nsys ]] \\
                       || [[ "\$comm" == QdstrmImporter ]] \\
                       || [[ "\$cmd" == *QdstrmImporter* ]] \\
                       || [[ "\$cmd" == nsys\\ * ]]; then
                        n=\$((n + 1))
                    fi
                done
                echo \$n
            }
            _count_events() {
                local n
                n=\$(grep -c "nsys_report_complete" "\$EVT_LOG" 2>/dev/null)
                # grep -c with no match exits 1 but outputs "0" — both branches
                # would write to N_EVT via 'echo 0' fallback. Bypass that:
                echo "\${n:-0}"
            }

            while [[ \$(( \$(date +%s) - T0 )) -lt \$DRAIN ]]; do
                ELAPSED=\$(( \$(date +%s) - T0 ))
                N_REPORTS=\$(_count_reports)
                N_PROC=\$(_count_session_procs "\$SESSION_DIR")

                # Primary signal: .nsys-rep file count has stabilised AND
                # we've waited at least MIN_WAIT. (Files appear at the very
                # end of finalize, so seeing the count stop incrementing for
                # K seconds means all finalisers are done.)
                if [[ "\$N_REPORTS" == "\$REPORT_LAST" ]]; then
                    REPORT_STABLE_FOR=\$(( REPORT_STABLE_FOR + 1 ))
                    if [[ \$REPORT_STABLE_FOR -ge 8 && \$ELAPSED -ge \$MIN_WAIT ]]; then
                        echo "[FISH] nsys drain: .nsys-rep count stable=\$N_REPORTS for 8s (waited \${ELAPSED}s)"
                        break
                    fi
                else
                    REPORT_STABLE_FOR=0
                    REPORT_LAST=\$N_REPORTS
                fi

                # Secondary signal: no nsys-family processes AND no reports growing
                if [[ \$ELAPSED -ge \$MIN_WAIT && "\$N_PROC" -eq 0 && \$REPORT_STABLE_FOR -ge 3 ]]; then
                    echo "[FISH] nsys drain: no nsys procs + reports stable=\$N_REPORTS (waited \${ELAPSED}s)"
                    break
                fi
                sleep 1
            done
            ELAPSED=\$(( \$(date +%s) - T0 ))
            FINAL_REPORTS=\$(_count_reports)
            FINAL_PROC=\$(_count_session_procs "\$SESSION_DIR")
            FINAL_EVT=\$(_count_events)
            echo "[FISH] nsys drain done: .nsys-rep files=\$FINAL_REPORTS, events=\$FINAL_EVT, procs=\$FINAL_PROC, waited=\${ELAPSED}s"
        fi
    fi

    # 3. Destroy the LTTng sessions (stopped in step 0; a second stop is a no-op)
    echo "[FISH] Destroying trace session..."
    SESSION=\$(cat \$FISH_SESSION_NAME_FILE 2>/dev/null)
    if [[ -n "\$SESSION" ]]; then
        lttng stop "\$SESSION" >/dev/null 2>&1 || true
        lttng destroy "\$SESSION" 2>&1 | tee -a "\$SESSION_DIR/fishlog/lttng_stop.txt" | grep -i "discard" || true
    fi
    KSESSION=\$(cat /tmp/fish_ksession_name 2>/dev/null)
    if [[ -n "\$KSESSION" ]]; then
        lttng stop "\$KSESSION" >/dev/null 2>&1 || true
        lttng destroy "\$KSESSION" >> "\$SESSION_DIR/fishlog/lttng_kernel_stop.txt" 2>&1 || true
        rm -f /tmp/fish_ksession_name
    fi
    # Discard report: LTTng ring-buffer overflows silently drop events; make
    # every session declare its own loss (probe-effect / completeness line).
    # FISH_EVENT_COUNT=0 defers the (slow: one full babeltrace pass) count —
    # campaigns count offline; the discard warning still comes from lttng stop.
    if [[ "\${FISH_EVENT_COUNT:-1}" == "0" && -n "\$SESSION_DIR" ]]; then
        NDISC=\$(grep -oiE '[0-9]+ events? were discarded' "\$SESSION_DIR/fishlog/lttng_stop.txt" 2>/dev/null | awk '{s+=\$1} END{print s+0}')
        echo "total_discarded_events=\$NDISC" > "\$SESSION_DIR/fishlog/discards.txt"
        echo "total_events=deferred" >> "\$SESSION_DIR/fishlog/discards.txt"
        echo "[FISH] LTTng events: deferred (FISH_EVENT_COUNT=0), discarded (lttng stop): \$NDISC"
    elif [[ -n "\$SESSION_DIR" ]] && command -v babeltrace2 >/dev/null 2>&1; then
        TRACE_ROOT=\$(find "\$SESSION_DIR/ros2" -name metadata -printf '%h\\n' 2>/dev/null | head -1)
        if [[ -n "\$TRACE_ROOT" ]]; then
            # single pass: events on stdout (counted), discard warnings on stderr
            NEV=\$(babeltrace2 "\$TRACE_ROOT" 2> "\$SESSION_DIR/fishlog/discards.txt" | wc -l)
            NDISC=\$(grep -oE 'discarded [0-9]+' "\$SESSION_DIR/fishlog/discards.txt" | awk '{s+=\$2} END{print s+0}')
            echo "total_discarded_events=\$NDISC" >> "\$SESSION_DIR/fishlog/discards.txt"
            echo "total_events=\$NEV" >> "\$SESSION_DIR/fishlog/discards.txt"
            echo "[FISH] LTTng events: \$NEV, discarded: \$NDISC (fishlog/discards.txt)"
            if [[ "\$NEV" -eq 0 ]]; then
                echo "[FISH] ERROR: EMPTY TRACE — no UST events recorded. Check /dev/shm size vs LTTng buffers (--shm-size) and that apps sourced the overlay."
            fi
        else
            echo "total_discarded_events=0  # no UST streams found (no traced app registered)" > "\$SESSION_DIR/fishlog/discards.txt"
        fi
    fi
    TPID=\$(cat /tmp/fish_trace_pid 2>/dev/null)
    if [[ -n "\$TPID" && "\$TPID" =~ ^[0-9]+$ ]]; then
        # The pipeline runs in its own process group (setsid in start_session).
        # Kill the whole group so the inner 'sleep infinity' subshell and
        # the ros2 trace process die together. Without this the container
        # never exits cleanly after dec/auto_stop.
        kill -TERM -\$TPID 2>/dev/null
        sleep 0.5
        kill -KILL -\$TPID 2>/dev/null
        # Belt-and-suspenders: also kill by PID in case the group kill missed
        # something (e.g. setsid not available, pre-existing single-PID install).
        kill \$TPID 2>/dev/null
    fi
    [[ -n "\$SESSION_DIR" ]] && date +%s > "\$SESSION_DIR/fishlog/stop_done.txt"   # end-of-stop marker (runner waits for it)
    rm -f \$FISH_COUNTER \$FISH_SESSION_NAME_FILE \$FISH_SESSION_DIR_FILE /tmp/fish_trace_pid \
         /tmp/fish_launch_output.log /tmp/fish_system_stable \
         /tmp/fish_gpu_handler_complete /tmp/fish_replay_complete
    if [[ -n "\$SESSION_DIR" ]]; then
        chmod -R a+rX "\$SESSION_DIR" 2>/dev/null
        echo "[FISH] Session stopped. Output: \$SESSION_DIR/"
    else
        echo "[FISH] Session stopped."
    fi
}

get_status() {
    COUNT=\$(cat \$FISH_COUNTER 2>/dev/null || echo 0)
    SESSION=\$(cat \$FISH_SESSION_NAME_FILE 2>/dev/null || echo "none")
    SESSION_DIR=\$(cat \$FISH_SESSION_DIR_FILE 2>/dev/null || echo "none")
    if [[ "\$SESSION" != "none" ]] && lttng list "\$SESSION" &>/dev/null; then
        echo "[FISH] Session '\$SESSION' active, \$COUNT node(s) tracked"
        echo "[FISH] Output: \$SESSION_DIR/"
    else
        echo "[FISH] No active session"
    fi
    PYTHONPATH=\$FISH_PYTHON:\$PYTHONPATH python3 -m fish.cli gpu daemon status 2>/dev/null
}

increment_counter() {
    COUNT=\$(cat \$FISH_COUNTER 2>/dev/null || echo 0)
    echo \$((COUNT + 1)) > \$FISH_COUNTER
    echo "[FISH] Node starting (\$((COUNT + 1)) active)"
}

decrement_counter() {
    COUNT=\$(cat \$FISH_COUNTER 2>/dev/null || echo 1)
    echo \$((COUNT - 1)) > \$FISH_COUNTER
    if [[ \$((COUNT - 1)) -le 0 ]]; then
        echo "[FISH] Last node exited, stopping trace session..."
        stop_session
        return 0
    else
        echo "[FISH] Node exited, \$((COUNT - 1)) still active"
        return 1
    fi
}

case "\$1" in
    start)   start_session ;;
    stop)    stop_session ;;
    status)  get_status ;;
    inc)     increment_counter ;;
    dec)     decrement_counter ;;
    *)       echo "Usage: trace_session.sh {start|stop|status|inc|dec}" ;;
esac
TRACE_EOF
chmod +x $FISH_SCRIPTS/trace_session.sh

# --- Generate ros2 wrapper (bash) ---
cat > $FISH_BIN/ros2 << WRAPPER_EOF
#!/bin/bash
# FISH ros2 wrapper (generated by install_fish.sh)

REAL_ROS2=\$(which -a ros2 | grep -v /fish/bin | head -1)
FISH_ROOT=/opt/ros/humble/fish
FISH_SCRIPTS=\$FISH_ROOT/scripts
FISH_PYTHON=\$FISH_ROOT/python

# --- FISH subcommands ---
if [[ "\$1" == "run" && "\$2" == "fish" ]]; then
    case "\$3" in
        stop)
            \$FISH_SCRIPTS/trace_session.sh stop
            exit 0
            ;;
        status)
            \$FISH_SCRIPTS/trace_session.sh status
            exit 0
            ;;
        gpu)
            PYTHONPATH=\$FISH_PYTHON:\$PYTHONPATH python3 -m fish.cli gpu "\${@:4}"
            exit \$?
            ;;
        snapshot)
            PYTHONPATH=\$FISH_PYTHON:\$PYTHONPATH python3 -m fish.cli snapshot "\${@:4}"
            exit \$?
            ;;
        "")
            echo "Lurking in depths..."
            exit 0
            ;;
        *)
            echo "[FISH] Unknown command: \$3"
            echo "Available: stop, status, gpu, snapshot"
            exit 1
            ;;
    esac
fi

# --- Automatic tracing when FISH_ENABLED=1 ---
if [[ "\$FISH_ENABLED" == "1" && ("\$1" == "run" || "\$1" == "launch") ]]; then
    # --- LTTng-UST registration guard (2026-08-24) ---
    # A traced process must register with lttng-sessiond before its first
    # tracepoint; the default LTTNG_UST_REGISTER_TIMEOUT is 3000 ms, after
    # which the app runs UNTRACED until registration completes. When a launch
    # group starts ~20 processes at once (Autoware planning+control, r24:
    # first events 41-43 s), sessiond falls behind and the first seconds —
    # rcl_node_init, callback registrations, component loads — are lost
    # silently (discard counter stays 0): 26 nodes missing, 11.5 % of
    # callback executions unattributable. -1 = wait for registration.
    export LTTNG_UST_REGISTER_TIMEOUT=\${LTTNG_UST_REGISTER_TIMEOUT:--1}
    # --- RMW guard (2026-08-16) ---
    # Non-interactive shells (bash -lc, docker run ... bash -c) do NOT source
    # ~/.bashrc, so an image-level "export RMW_IMPLEMENTATION=..." there is
    # silently lost and ROS 2 falls back to rmw_fastrtps_cpp. Five Autoware
    # sessions produced 0 CUDA kernels for exactly this reason. Resolution
    # order: (1) env already set → keep; (2) [ros] rmw_implementation in
    # fish_settings.ini → export it; (3) leave unset but say so loudly.
    if [[ -z "\$RMW_IMPLEMENTATION" ]]; then
        INI_RMW=\$(python3 - <<'PYRMW' 2>/dev/null
import configparser
c = configparser.ConfigParser(inline_comment_prefixes=("#", ";"))
c.read("/opt/ros/humble/fish/fish_settings.ini")
print(c.get("ros", "rmw_implementation", fallback="").strip())
PYRMW
)
        if [[ -n "\$INI_RMW" ]]; then
            export RMW_IMPLEMENTATION="\$INI_RMW"
            echo "[FISH] RMW_IMPLEMENTATION was unset → using '\$INI_RMW' from fish_settings.ini [ros]"
        else
            echo "[FISH] WARNING: RMW_IMPLEMENTATION unset → ROS 2 default (rmw_fastrtps_cpp)."
            echo "[FISH]          Autoware requires rmw_cyclonedds_cpp; set it in the env or in"
            echo "[FISH]          fish_settings.ini [ros] rmw_implementation."
        fi
    fi
    echo "[FISH] Effective RMW_IMPLEMENTATION=\${RMW_IMPLEMENTATION:-<unset → rmw_fastrtps_cpp>}"

    # CycloneDDS config: without CYCLONEDDS_URI Cyclone runs with
    # MaxMessageSize ~14.7 kB and default socket buffers → large sensor
    # frames (top Velodyne ~600 kB) get lost in IP-fragment reassembly.
    if [[ "\$RMW_IMPLEMENTATION" == "rmw_cyclonedds_cpp" && -z "\$CYCLONEDDS_URI" ]]; then
        INI_CDDS=\$(python3 - <<'PYCDDS' 2>/dev/null
import configparser
c = configparser.ConfigParser(inline_comment_prefixes=("#", ";"))
c.read("/opt/ros/humble/fish/fish_settings.ini")
print(c.get("ros", "cyclonedds_uri", fallback="").strip())
PYCDDS
)
        if [[ -n "\$INI_CDDS" ]]; then
            case "\$INI_CDDS" in
                file://*|/*) CDDS_URI="\$INI_CDDS" ;;
                *)           CDDS_URI="file://\$FISH_ROOT/\$INI_CDDS" ;;
            esac
            CDDS_PATH="\${CDDS_URI#file://}"
            if [[ -f "\$CDDS_PATH" ]]; then
                export CYCLONEDDS_URI="\$CDDS_URI"
                echo "[FISH] CYCLONEDDS_URI was unset → using '\$CDDS_URI' from fish_settings.ini [ros]"
            else
                echo "[FISH] WARNING: [ros] cyclonedds_uri points to missing file: \$CDDS_PATH"
            fi
        else
            echo "[FISH] NOTE: CYCLONEDDS_URI unset (Cyclone defaults: MaxMessageSize ~14.7kB) —"
            echo "[FISH]       Autoware needs config/cyclonedds_autoware.xml; set [ros] cyclonedds_uri."
        fi
    fi
    echo "[FISH] Effective CYCLONEDDS_URI=\${CYCLONEDDS_URI:-<unset>}"

    \$FISH_SCRIPTS/trace_session.sh start
    trap "\$FISH_SCRIPTS/trace_session.sh stop; exit 0" SIGTERM SIGINT
    \$FISH_SCRIPTS/trace_session.sh inc

    # Inspect the launch file to extract composable node specs.
    # Only runs for 'ros2 launch' (skip 'ros2 run'). Output goes to
    # \$SESSION_DIR/launch_components.json. Errors are non-fatal —
    # the wrapper continues even if inspection fails.
    if [[ "\$1" == "launch" ]]; then
        SESSION_DIR=\$(cat /tmp/fish_session_dir 2>/dev/null)
        if [[ -n "\$SESSION_DIR" && \$# -ge 3 ]]; then
            LAUNCH_COMPONENTS_JSON="\$SESSION_DIR/launch_components.json"
            echo "[FISH] Inspecting launch file: \$2 \$3"
            PYTHONPATH=\$FISH_PYTHON:\$PYTHONPATH python3 -m fish.launch_inspect \\
                "\$2" "\$3" "\${@:4}" \\
                > "\$LAUNCH_COMPONENTS_JSON" \\
                2> "\$SESSION_DIR/fishlog/launch_inspect.log" || true
            if [[ -s "\$LAUNCH_COMPONENTS_JSON" ]]; then
                N_CONT=\$(python3 -c "import json; d=json.load(open('\$LAUNCH_COMPONENTS_JSON')); print(len(d))" 2>/dev/null || echo "?")
                echo "[FISH] Launch inspector: \$N_CONT containers captured"
            else
                echo "[FISH] Launch inspector produced no output (see fishlog/launch_inspect.log)"
            fi
        fi
    fi

    # Tee launch stdout for executor_started stability monitoring
    FISH_LAUNCH_LOG=/tmp/fish_launch_output.log
    > \$FISH_LAUNCH_LOG

    # For 'ros2 launch' we route through fish.launch_wrap so that
    # composable node containers are started with nsys from the very
    # first moment (no kill/reload needed). For 'ros2 run' we fall back
    # to the real ros2 binary unchanged.
    # FISH_GOMP_SHIM=1 (default, 2026-10-03, A0.2): preload libfish_gomp_shim.so (overlay tracetools lib dir)
    # into every launched process — interposes GOMP_parallel and emits ros2:fish_gomp_parallel(_end) so OpenMP
    # regions are visible per callback. Harmless for processes that never call libgomp.
    if [[ "\${FISH_GOMP_SHIM:-1}" == 1 ]] && [[ "\$1" == "launch" ]]; then
        SHIM=\$(ldconfig -p 2>/dev/null | grep -m1 -o '/[^ ]*libfish_gomp_shim.so')
        [[ -z "\$SHIM" ]] && SHIM=\$(find /root/trace_overlay_ws/install/tracetools/lib -name libfish_gomp_shim.so 2>/dev/null | head -1)
        if [[ -n "\$SHIM" ]]; then
            export LD_PRELOAD="\$SHIM\${LD_PRELOAD:+:\$LD_PRELOAD}"
            export FISH_GOMP_SHIM_PATH="\$SHIM"   # launch_wrap strips LD_PRELOAD for nsys and re-adds the shim for the target
            echo "[FISH] OpenMP shim preloaded: \$SHIM"
        else
            echo "[FISH] NOTE: libfish_gomp_shim.so not found (image < fishwait16) — OpenMP regions not traced"
        fi
    fi
    # FISH_LOCK_SHIM=1 (default 0, 2026-10-05, image >= fishwait24): preload libfish_lock_shim.so — per callback
    # instance, which application mutexes it locks and for how long (ros2:fish_lock; enable the event with
    # FISH_EXTRA_EVENTS, the shim collects nothing while it is off).
    if [[ "\${FISH_LOCK_SHIM:-0}" == 1 ]] && [[ "\$1" == "launch" ]]; then
        LSHIM=\$(find /root/trace_overlay_ws/install/tracetools/lib -name libfish_lock_shim.so 2>/dev/null | head -1)
        if [[ -n "\$LSHIM" ]]; then
            export LD_PRELOAD="\$LSHIM\${LD_PRELOAD:+:\$LD_PRELOAD}"
            echo "[FISH] lock shim preloaded: \$LSHIM"
        else
            echo "[FISH] NOTE: libfish_lock_shim.so not found (image < fishwait24) — application locks not traced"
        fi
    fi
    if [[ "\$1" == "launch" ]]; then
        PYTHONPATH=\$FISH_PYTHON:\$PYTHONPATH python3 -m fish.launch_wrap \\
            "\${@:2}" > >( tee -a \$FISH_LAUNCH_LOG ) 2>&1 &
    else
        \$REAL_ROS2 "\$@" > >( tee -a \$FISH_LAUNCH_LOG ) 2>&1 &
    fi
    NODE_PID=\$!
    wait \$NODE_PID 2>/dev/null
    EXIT_CODE=\$?

    \$FISH_SCRIPTS/trace_session.sh dec
    exit \$EXIT_CODE
fi

exec \$REAL_ROS2 "\$@"
WRAPPER_EOF
chmod +x $FISH_BIN/ros2

# --- Generate launch_test wrapper (bash) ---
# Parallels the ros2 wrapper for the launch_testing entry point used by
# Isaac ROS Benchmark and other pytest-style integration suites.
cat > $FISH_BIN/launch_test << WRAPPER_EOF
#!/bin/bash
# FISH launch_test wrapper (generated by install_fish.sh)

REAL_LT=\$(which -a launch_test 2>/dev/null | grep -v /fish/bin | head -1)
FISH_ROOT=/opt/ros/humble/fish
FISH_SCRIPTS=\$FISH_ROOT/scripts
FISH_PYTHON=\$FISH_ROOT/python

# Locate the first positional argument (the test script path).
# launch_test may receive flags like --xml-output, --launch-arg, etc.
# before the script path; we just grab the first non-flag argument.
TEST_SCRIPT=""
for a in "\$@"; do
    case "\$a" in
        -*) ;;
        *)  TEST_SCRIPT="\$a"; break ;;
    esac
done

# --- Automatic tracing when FISH_ENABLED=1 ---
if [[ "\$FISH_ENABLED" == "1" ]]; then
    export LTTNG_UST_REGISTER_TIMEOUT=\${LTTNG_UST_REGISTER_TIMEOUT:--1}   # see ros2 wrapper: never run untraced
    \$FISH_SCRIPTS/trace_session.sh start
    trap "\$FISH_SCRIPTS/trace_session.sh stop; exit 0" SIGTERM SIGINT
    \$FISH_SCRIPTS/trace_session.sh inc

    # Inspect the test script's generate_test_description() to extract
    # composable node + standalone node specs. Output goes to
    # \$SESSION_DIR/launch_components.json. Errors are non-fatal.
    SESSION_DIR=\$(cat /tmp/fish_session_dir 2>/dev/null)
    if [[ -n "\$SESSION_DIR" && -n "\$TEST_SCRIPT" ]]; then
        LAUNCH_COMPONENTS_JSON="\$SESSION_DIR/launch_components.json"
        echo "[FISH] Inspecting launch_test: \$TEST_SCRIPT"
        PYTHONPATH=\$FISH_PYTHON:\$PYTHONPATH python3 -m fish.launch_test_inspect \\
            "\$TEST_SCRIPT" \\
            > "\$LAUNCH_COMPONENTS_JSON" \\
            2> "\$SESSION_DIR/fishlog/launch_inspect.log" || true
        if [[ -s "\$LAUNCH_COMPONENTS_JSON" ]]; then
            N_CONT=\$(python3 -c "import json; d=json.load(open('\$LAUNCH_COMPONENTS_JSON')); print(len(d))" 2>/dev/null || echo "?")
            echo "[FISH] launch_test inspector: \$N_CONT containers captured"
        else
            echo "[FISH] launch_test inspector produced no output (see fishlog/launch_inspect.log)"
        fi
    fi

    # Tee launch stdout for executor_started stability monitoring
    FISH_LAUNCH_LOG=/tmp/fish_launch_output.log
    > \$FISH_LAUNCH_LOG

    # Run real launch_test through fish.launch_test_wrap so the
    # Node.execute / ComposableNodeContainer.execute monkey-patches are
    # installed BEFORE launch_testing instantiates LaunchService. Same
    # engine as ros2 launch ⇒ same patches apply, GPU nodes spawn under
    # nsys from t=0.
    PYTHONPATH=\$FISH_PYTHON:\$PYTHONPATH python3 -m fish.launch_test_wrap \\
        "\$@" > >( tee -a \$FISH_LAUNCH_LOG ) 2>&1 &
    NODE_PID=\$!
    wait \$NODE_PID 2>/dev/null
    EXIT_CODE=\$?

    \$FISH_SCRIPTS/trace_session.sh dec
    exit \$EXIT_CODE
fi

exec \$REAL_LT "\$@"
WRAPPER_EOF
chmod +x $FISH_BIN/launch_test

# --- Set up PATH and PYTHONPATH ---
export PATH=$FISH_BIN:$PATH
grep -q "fish/bin" ~/.bashrc || echo "export PATH=$FISH_BIN:\$PATH" >> ~/.bashrc
export PYTHONPATH=$FISH_PYTHON:$PYTHONPATH
grep -q "fish/python" ~/.bashrc || echo "export PYTHONPATH=$FISH_PYTHON:\$PYTHONPATH" >> ~/.bashrc

EVENT_COUNT=$(echo $EVENTS | wc -w)
echo "[FISH] Setup complete ($EVENT_COUNT events, settings loaded)"
echo "ros2 -> $(which ros2)"
echo ""
echo "Commands:"
echo "  export FISH_ENABLED=1         # enable auto-tracing"
echo "  export FISH_ENABLED=0         # disable auto-tracing (ros2 works normally)"
echo "  ros2 run <pkg> <node>         # auto-traced when FISH_ENABLED=1"
echo "  ros2 launch <pkg> <file>      # auto-traced when FISH_ENABLED=1"
echo "  ros2 run fish                 # wrapper test"
echo "  ros2 run fish status          # session + daemon info"
echo "  ros2 run fish stop            # stop (snapshot + flush + save)"
echo "  ros2 run fish snapshot        # manual shutdown snapshot"
echo "  ros2 run fish gpu             # list GPU processes"
echo "  ros2 run fish gpu relaunch    # manual nsys relaunch"
echo "  ros2 run fish gpu daemon fg   # run daemon in foreground"
echo ""
echo "Settings: $FISH_ROOT/fish_settings.ini"
